BEGIN TRANSACTION;
CREATE TABLE `inbounds` (`id` integer,`user_id` integer,`up` integer,`down` integer,`total` integer,`remark` text,`sub_sort_index` integer DEFAULT 1,`exclude_from_sub` numeric DEFAULT false,`enable` numeric,`expiry_time` integer,`traffic_reset` text DEFAULT "never",`traffic_reset_day` integer DEFAULT 1,`last_traffic_reset_time` integer DEFAULT 0,`listen` text,`port` integer,`protocol` text,`settings` text,`stream_settings` text,`tag` text UNIQUE,`sniffing` text,`node_id` integer,`share_addr_strategy` text DEFAULT "node",`share_addr` text,`disable_flow` numeric DEFAULT false,`origin_node_guid` text,PRIMARY KEY (`id`));
CREATE TABLE `clients` (`id` integer,`email` text NOT NULL UNIQUE,`sub_id` text,`uuid` text,`password` text,`auth` text,`flow` text,`security` text,`reverse` text,`wg_private_key` text,`wg_public_key` text,`wg_allowed_ips` text,`wg_pre_shared_key` text,`wg_keep_alive` integer DEFAULT 0,`wg_forwarded_ports` text,`secret` text,`ad_tag` text DEFAULT '',`limit_ip` integer,`limit_hwid` integer DEFAULT 0,`total_gb` integer,`expiry_time` integer,`enable` numeric DEFAULT true,`tg_id` integer,`group_name` text DEFAULT '',`comment` text,`reset` integer DEFAULT 0,`reset_day` integer DEFAULT 0,`reset_weekday` integer DEFAULT 0,`reset_max` integer DEFAULT 0,`traffic_reset` text DEFAULT 'never',`traffic_reset_day` integer DEFAULT 1,`created_at` integer,`updated_at` integer,`sync_orphaned_at` integer DEFAULT 0,PRIMARY KEY (`id`));
CREATE TABLE `client_inbounds` (`client_id` integer,`inbound_id` integer,`flow_override` text,`created_at` integer,PRIMARY KEY (`client_id`,`inbound_id`));
CREATE TABLE `client_traffics` (`id` integer,`inbound_id` integer,`enable` numeric,`email` text UNIQUE,`up` integer,`down` integer,`expiry_time` integer,`total` integer,`reset` integer DEFAULT 0,`reset_day` integer DEFAULT 0,`reset_weekday` integer DEFAULT 0,`reset_max` integer DEFAULT 0,`reset_count` integer DEFAULT 0,`last_online` integer DEFAULT 0,PRIMARY KEY (`id`));
CREATE TABLE `settings` (`id` integer,`key` text,`value` text,PRIMARY KEY (`id`));
COMMIT;
